const React=require('react'),{createRoot}=require('react-dom/client');
const {DashboardLoadingProgress}=require('../../components/dashboard/dashboard-loading-progress.tsx');
const {beginForegroundLoading}=require('../../lib/display/foreground-loading.ts');
const {BotDraftSettings}=require('../../components/settings/bot-draft-settings.tsx');
const b='00000000-0000-4000-8000-000000000001',c='00000000-0000-4000-8000-000000000002',c2='00000000-0000-4000-8000-000000000003';
const tables=new Map(),requests=[];
window.fetch=async(url,init={})=>{requests.push({url,method:init.method??'GET'});if(url.includes('scope=drafts'))return Response.json({businessId:b,canManage:true,pages:[{id:c,platform:'facebook',account_name:'Fixture Page',platform_account_id:'123'},{id:c2,platform:'facebook',account_name:'Other Page',platform_account_id:'456'}],members:[]});if(init.method==='POST'){const body=JSON.parse(init.body),old=tables.get(body.channelId);if(body.revision!==(old?.revision??0))return Response.json({error:'Revision conflict'},{status:409});tables.set(body.channelId,{rules:body.rules,revision:(old?.revision??0)+1});return Response.json({success:true,revision:(old?.revision??0)+1,enabled:false});}const channel=new URL(url,location.origin).searchParams.get('channelId');return Response.json(tables.get(channel)??{rules:[],revision:0});};
createRoot(document.getElementById('root')).render(React.createElement(React.Fragment,null,React.createElement('header',{id:'header',style:{position:'relative',height:72,width:800}},React.createElement(DashboardLoadingProgress)),React.createElement('div',{id:'content'},React.createElement(BotDraftSettings))));
const pause=ms=>new Promise(r=>setTimeout(r,ms)),checks=[],check=(name,value)=>{if(!value)throw Error(name);checks.push(name)};
const button=text=>[...document.querySelectorAll('button')].find(x=>x.textContent===text);
function setInput(node,value){Object.getOwnPropertyDescriptor(node.tagName==='SELECT'?HTMLSelectElement.prototype:node.tagName==='TEXTAREA'?HTMLTextAreaElement.prototype:HTMLInputElement.prototype,'value').set.call(node,value);node.dispatchEvent(new Event(node.tagName==='SELECT'?'change':'input',{bubbles:true}));}
(async()=>{try{await pause(100);const before=document.getElementById('content').getBoundingClientRect().top,first=beginForegroundLoading(),second=beginForegroundLoading();await pause(30);const bar=document.querySelector('[role="progressbar"]'),rect=bar.getBoundingClientRect();check('bar spans full header with three-pixel height',rect.width===800&&rect.height===3&&rect.top===document.getElementById('header').getBoundingClientRect().bottom-3);check('bar does not shift content',document.getElementById('content').getBoundingClientRect().top===before);check('accessible indeterminate loading has no invented percent',bar.getAttribute('aria-label')==='Loading'&&!bar.hasAttribute('aria-valuenow'));first();await pause(30);check('concurrent work retains indicator',!!document.querySelector('[role="progressbar"]'));second();await pause(30);check('completion removes indicator',!document.querySelector('[role="progressbar"]'));const channel=document.querySelector('select');setInput(channel,c);await pause(80);check('durable existing configuration loads before Save is enabled',!button('Save disabled rules').disabled);const input=label=>[...document.querySelectorAll('label')].find(x=>x.textContent.startsWith(label)).querySelector('input,textarea');setInput(input('Name'),'Fixture welcome');setInput(input('Reply / welcome template'),'Hello');setInput(input('Away template'),'We are away');await pause(30);button('Add session draft').click();await pause(40);check('actual editor adds a valid rule',document.querySelector('section ul').textContent.includes('Fixture welcome'));button('Save disabled rules').click();await pause(80);check('Save persists one disabled rule with revision',tables.get(c)?.rules.length===1&&tables.get(c).revision===1&&document.querySelector('section').textContent.includes('All rules remain disabled'));setInput(channel,c2);await pause(80);check('other channel does not inherit rules',!document.querySelector('section ul').textContent.includes('Fixture welcome'));setInput(channel,c);await pause(80);check('returning channel reloads persisted rule',document.querySelector('section ul').textContent.includes('Fixture welcome'));check('no provider or worker requests',requests.every(x=>x.url.startsWith('/api/tenh-bot/rules')||x.url==='/api/facebook/auto-reply?scope=drafts'));document.getElementById('result').textContent=JSON.stringify({passed:true,checks,requests});}catch(error){document.getElementById('result').textContent=JSON.stringify({passed:false,error:error.message,checks});}})();
